from produire import produire,paras,steps,table
from medicaments_suite import uveite
parts=[
('L’{uvéite antérieure aiguë} est une inflammation de l’iris et de la partie antérieure du corps ciliaire. Elle peut donner douleur, rougeur et photophobie. Une atteinte postérieure ou plus diffuse doit être recherchée.',paras('Les termes iritis et iridocyclite décrivent les structures atteintes dans l’uvée antérieure. Une uvéite intermédiaire, postérieure ou une panuvéite ne se résume pas au même tableau ni au même bilan.', 'L’inflammation est intraoculaire : un collyre lubrifiant ou un antibiotique de conjonctivite ne suffit pas à la caractériser. L’épisode peut être isolé, récidivant, infectieux ou lié à une inflammation générale.')),
('Le {contexte recherche récidive, infection et maladie inflammatoire}. Une cause n’est pas toujours identifiée. Spondyloarthrite, maladie intestinale inflammatoire et sarcoïdose font partie des associations.',paras('Les HUG citent également maladie de Behçet, médicaments et infections telles que syphilis ou tuberculose selon le tableau. Les infections virales et les atteintes postérieures ont leurs propres caractéristiques et investigations.', 'Le résumé européen décrit des récidives fréquentes et une proportion importante de cas sans cause retrouvée. Ces données générales ne sont pas une prévalence suisse ; l’étiquette idiopathique doit résulter d’une évaluation adaptée et non d’un bilan inexistant.')),
('Le {mécanisme associe inflammation et altération de la barrière intraoculaire}. Cellules et protéines peuvent devenir visibles dans la chambre antérieure. Des adhérences entre iris et cristallin peuvent se former.',paras('Les cellules inflammatoires et l’effet de diffusion de la lumière sont appréciés à la lampe à fente. Les synéchies postérieures peuvent rendre la pupille irrégulière et compliquer la circulation de l’humeur aqueuse.', 'La pression peut être perturbée par la maladie, ses complications ou le traitement. Une baisse visuelle peut aussi résulter d’une atteinte d’autres structures ; une amélioration de la rougeur ne garantit donc pas la disparition de toute inflammation.')),
('Le {tri impose un avis ophtalmologique urgent}. Les HUG recommandent d’appeler pour toute suspicion d’uvéite. Ne pas débuter un corticoïde sur une rougeur non examinée.',paras('Douleur profonde, photophobie et baisse visuelle sont des signes d’alarme. Un hypopion, une chirurgie récente ou une aggravation rapide demande aussi d’envisager une infection intraoculaire, avec prise en charge immédiate.', 'Le parcours britannique décrit une prise en charge de certaines formes simples par des optométristes formés. Cette organisation ne remplace pas la recommandation suisse d’orientation urgente ni l’exclusion d’une kératite ou d’un glaucome.')),
('L’{anamnèse précise les signes oculaires et extraoculaires}. Demander épisodes antérieurs, traitements et évolution de la vision. Rechercher les symptômes qui orientent le bilan étiologique.',paras('Interroger selon le contexte sur douleurs rachidiennes inflammatoires, arthrites, symptômes intestinaux, aphtes récurrents, lésions cutanées, symptômes respiratoires et exposition infectieuse. Leur présence guide les tests ; leur absence n’exclut pas toute maladie associée.', 'Relever chirurgie, traumatisme, immunodépression et médicaments récents. Avant une corticothérapie ou un mydriatique, préciser glaucome connu, réactions médicamenteuses, âge, grossesse et allaitement.')),
('L’{examen spécialisé confirme l’inflammation antérieure}. Mesurer vision et pression puis examiner cornée, pupille et chambre antérieure. Le fond d’œil recherche une atteinte plus étendue.',paras('La lampe à fente identifie cellules, protéines, précipités et éventuelles synéchies. Une pupille petite ou irrégulière peut orienter, mais n’est pas nécessaire à tous les cas.', 'Vérifier une lésion épithéliale cornéenne avant tout corticoïde. La pression doit être interprétée avec l’état de l’angle et les traitements. La dilatation diagnostique ou thérapeutique est décidée après cette évaluation.')),
('L’{approche syndromique évite de confondre plusieurs urgences}. Une photophobie avec rougeur péricornéenne suggère une atteinte profonde. L’examen distingue cornée, uvée, sclère et pression.',table(['Présentation','Diagnostic à discuter'],[['Douleur et photophobie, inflammation de chambre antérieure.','Uvéite antérieure.'],['Infiltrat ou ulcération cornéenne.','Kératite infectieuse ou autre atteinte de surface.'],['Halos, nausées, cornée œdémateuse, pression élevée.','Crise de fermeture d’angle.'],['Douleur profonde irradiée, rougeur sclérale.','Sclérite.'],['Après chirurgie avec baisse visuelle et inflammation importante.','Infection intraoculaire à exclure immédiatement.'],['Corps flottants ou scotome associés.','Explorer une atteinte intermédiaire ou postérieure.']])) ,
('Le {diagnostic positif repose sur la lampe à fente}. Les symptômes seuls ne prouvent pas une uvéite. Le spécialiste précise localisation, gravité et complications.',paras('L’identification d’une inflammation de chambre antérieure soutient le diagnostic. La recherche d’atteinte postérieure ou cornéenne détermine si le tableau est véritablement limité à l’avant de l’œil.', 'Un marqueur génétique ou une sérologie positive ne prouve pas isolément la cause de l’épisode. Une réponse aux corticoïdes ne suffit pas non plus à exclure une infection, dont les signes peuvent être masqués.')),
('Le {bilan étiologique est guidé par le phénotype et les récidives}. Les investigations ne sont pas identiques pour tous les patients. Une forme récidivante, bilatérale ou atypique justifie une recherche adaptée.',paras('L’ophtalmologue et le médecin traitant choisissent analyses, imagerie et avis spécialisés selon les signes. Les HUG citent notamment les causes infectieuses et inflammatoires ; la sélection doit répondre à une hypothèse clinique.', 'Les tests pour syphilis, tuberculose, maladies inflammatoires ou prédispositions génétiques ne sont pas interchangeables. Les examens intraoculaires spécialisés relèvent d’une indication précise. Un bilan systémique ne doit pas retarder les soins oculaires urgents.')),
('L’{algorithme traite l’inflammation après identification du cadre}. L’avis urgent précède l’application d’un schéma de corticoïde. La surveillance recherche pression et complications.',steps('Mesurer la vision et identifier chirurgie, infection possible et signes de gravité.', 'Obtenir l’évaluation ophtalmologique urgente avec cornée, chambre antérieure, pression et fond d’œil selon indication.', 'Déterminer si le processus est non infectieux et limité au segment antérieur.', 'Prescrire anti-inflammatoire et éventuellement cycloplégique compatibles avec le terrain et les contre-indications.', 'Organiser contrôle rapproché et réduction du traitement selon l’examen.', 'Rechercher une cause générale de façon ciblée, notamment si récidives ou présentation atypique.')),
('La {prise en charge suisse dépend de la cause et de la pression}. Une uvéite non infectieuse peut nécessiter un corticoïde local. Une cycloplégie peut prévenir ou traiter les synéchies selon l’indication.',paras('Le traitement est prescrit après examen ; une uvéite infectieuse peut nécessiter un traitement anti-infectieux spécifique. Une atteinte plus étendue ou résistante peut demander des médicaments systémiques ou d’autres interventions spécialisées.', '@@MEDICAMENTS@@', 'Les deux exemples ne forment pas une association obligatoire. Le glaucome figure parmi leurs contre-indications et l’association d’un corticoïde avec un mydriatique peut augmenter le risque d’hypertonie. Le choix de la spécialité et la surveillance sont donc essentiels.', 'Le suivi contrôle activité inflammatoire, vision, pression et tolérance. La diminution progressive du corticoïde repose sur les signes cliniques ; ne pas inventer un calendrier identique pour toutes les uvéites.')),
('La {prévention vise les récidives et les complications thérapeutiques}. Traiter une maladie associée lorsque cela est indiqué. Expliquer les signes qui imposent un retour rapide.',paras('Informer sur douleur nouvelle, baisse visuelle, photophobie accrue et mauvaise tolérance. Vérifier observance et technique d’instillation ; ne pas réutiliser spontanément une ancienne ordonnance de corticoïde lors d’une rougeur différente.', 'Des contrôles réguliers recherchent hypertonie, cataracte et complications de l’inflammation. Les contraintes de conduite sous atropine et la surveillance spécifique de l’enfant doivent être comprises par le patient et les proches.')),
('Le {point clé} est de confirmer l’inflammation intraoculaire avant de traiter. La cause infectieuse et la pression influencent la prescription. La disparition des symptômes ne remplace pas le contrôle spécialisé.',paras('Les soins urgents et le bilan étiologique sont complémentaires. La corticothérapie non surveillée peut masquer une infection et produire des complications, même lorsque la rougeur s’améliore.'))]
quiz=[('Quelle région est atteinte dans une uvéite antérieure ?','L’iris et la partie antérieure du corps ciliaire.'),('La photophobie suffit-elle à confirmer le diagnostic ?','Non, l’examen spécialisé est nécessaire.'),('Quelle orientation les HUG recommandent-ils devant une suspicion ?','Un appel ophtalmologique urgent.'),('Quel instrument confirme l’inflammation de chambre antérieure ?','La lampe à fente.'),('Que sont les synéchies postérieures ?','Des adhérences entre l’iris et le cristallin.'),('Une cause générale est-elle toujours retrouvée ?','Non.'),('Un bilan identique pour tous est-il justifié ?','Non, il dépend du tableau et des récidives.'),('Peut-on débuter Maxidex sur un œil rouge inexpliqué ?','Non.'),('Les lésions cornéennes et le glaucome sont-ils des contre-indications de Maxidex citées ?','Oui.'),('Pourquoi mesurer régulièrement la pression sous corticoïde ?','Le traitement et la maladie peuvent l’augmenter.'),('L’atropine est-elle automatiquement sûre chez un patient avec angle étroit ?','Non, le glaucome à angle étroit figure parmi les contre-indications.'),('Que prévoit la notice d’atropine pour l’allaitement ?','Son interruption si le traitement est indiqué.'),('Peut-on conduire tant que l’atropine agit ?','Non, la notice interdit conduite et machines dangereuses pendant le traitement et les quelques jours suivants.'),('Une amélioration de la rougeur permet-elle d’arrêter seul le traitement ?','Non, la diminution et le suivi sont guidés par l’examen.')]
produire(8,parts,quiz,(1,20,22,24),uveite)
